// CheckoutForm.tsx
import { useState } from 'react';
import { useForm } from 'react-hook-form';

export function CheckoutForm({ onSubmit }) {
  const [step, setStep] = useState(1);
  const { register, handleSubmit, formState } = useForm();

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="max-w-md mx-auto space-y-4">
      {step === 1 && (
        <fieldset className="space-y-2">
          <legend className="font-medium">Shipping</legend>
          <input {...register('address')} placeholder="Address" className="w-full border rounded-md px-3 py-2" />
        </fieldset>
      )}
      {step === 2 && (
        <fieldset className="space-y-2">
          <legend className="font-medium">Payment</legend>
          <input {...register('card')} placeholder="Card number" className="w-full border rounded-md px-3 py-2" />
        </fieldset>
      )}
      {step === 3 && (
        <fieldset className="space-y-2">
          <legend className="font-medium">Review</legend>
          <button type="submit" className="w-full bg-black text-white rounded-md py-2">Place order</button>
        </fieldset>
      )}
      <div className="flex justify-between">
        {step > 1 && <button type="button" onClick={() => setStep(step - 1)}>Back</button>}
        {step < 3 && <button type="button" onClick={() => setStep(step + 1)}>Next</button>}
      </div>
    </form>
  );
}

