// CommandPalette.tsx
import { Command } from 'cmdk';

export function CommandPalette({ commands, open, onOpenChange }) {
  return (
    <Command.Dialog open={open} onOpenChange={onOpenChange} label="Command palette">
      <Command.Input placeholder="Type a command..." />
      <Command.List>
        {commands.map((c) => (
          <Command.Item key={c.id} onSelect={c.action}>{c.label}</Command.Item>
        ))}
      </Command.List>
    </Command.Dialog>
  );
}
